export default function ClientMarquee({
  clients,
}: {
  clients: readonly { name: string; icon: IconName }[];
}) {
  const track = [...clients, ...clients];

  return (
    <div
      className="marquee-mask relative w-full overflow-hidden"
      role="img"
      aria-label={`Highly experienced with: ${clients.map((c) => c.name).join(", ")}`}
    >
      <div className="marquee-track flex w-max items-center gap-10">
        {track.map((c, i) => (
          <span
            key={`${c.name}-${i}`}
            aria-hidden="true"
            className="flex h-[49px] w-[85.465px] shrink-0 items-center justify-center opacity-80"
          >
            <Icon name={c.icon} />
          </span>
        ))}
      </div>
    </div>
  );
}
